class Solution {
public:
    int maxAbsValExpr(vector<int>& arr1, vector<int>& arr2) {
        int n = arr1.size();
        long long ans = 0;
        for (int s1 = -1; s1 <= 1; s1 += 2) {
            for (int s2 = -1; s2 <= 1; s2 += 2) {
                for (int s3 = -1; s3 <= 1; s3 += 2) {
                    long long v0 = (long long)s1 * arr1[0] + (long long)s2 * arr2[0];
                    long long mx = v0, mn = v0;
                    for (int i = 1; i < n; i++) {
                        long long v = (long long)s1 * arr1[i]
                                    + (long long)s2 * arr2[i]
                                    + (long long)s3 * i;
                        if (v > mx) mx = v;
                        if (v < mn) mn = v;
                    }
                    long long diff = mx - mn;
                    if (diff > ans) ans = diff;
                }
            }
        }
        return (int)ans;
    }
};
